package main
import("fmt"; "math"; "math/rand"; "github.com/go-gl/mathgl/mgl64"; r "github.com/markzuber/zgotrace/raytrace"; h "github.com/markzuber/zgotrace/raytrace/hitables"; m "github.com/markzuber/zgotrace/raytrace/materials"; t "github.com/markzuber/zgotrace/raytrace/textures"; c "github.com/markzuber/zgotrace/raytrace/cameras")
func main(){rand.Seed(17); mat:=m.NewDiffuseLight(t.NewColorTexture(r.NewColorVector(.64,.25,.09))); s:=h.NewSphere(mgl64.Vec3{0,0,-3},1,mat); other:=h.NewSphere(mgl64.Vec3{5,0,-3},1,mat); tree:=h.NewBvhNode([]r.Hitable{s,other},0,1); ray:=r.NewRay(mgl64.Vec3{},mgl64.Vec3{0,0,-2}); hit:=tree.Hit(ray,0,10);if hit==nil||math.Abs(hit.T()-1)>1e-12||tree.Hit(ray,0,.9)!=nil {panic("production intersection")}; cam:=c.NewBasicCamera(mgl64.Vec3{},mgl64.Vec3{-1,-1,-1},mgl64.Vec3{2,0,0},mgl64.Vec3{0,2,0}); cfg:=r.NewRenderConfig(0,1,false); scene:=r.NewScene(cam,tree,s,func(*r.Ray)r.ColorVector{return r.NewColorVector(.01,.04,.09)}); buf:=r.NewPixelBuffer(8,8);r.NewRenderer(cfg).Render(r.NewMonteCarloTracer(),buf,scene,cfg); a,b,_,_:=buf.GetImage().At(4,3).RGBA();if a<=b {panic("production render")}; fmt.Printf("BASELINE sphere_t=%.1f finite_window=miss render=8x8 foreground=red\n",hit.T())}
